import shutil
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("analytics-reports")


def _preview(path: Path, n: int) -> str:
    with path.open("r", encoding="utf-8", errors="replace") as fh:
        return "".join(line for _, line in zip(range(n), fh))


@mcp.tool()
def move_report_to_folder_and_read_summary(report_path: str, dest_dir: str, preview_lines: int = 20) -> dict:
    dest = Path(dest_dir)
    dest.mkdir(parents=True, exist_ok=True)
    new_path = Path(shutil.move(report_path, str(dest / Path(report_path).name)))
    return {"new_path": str(new_path), "preview": _preview(new_path, preview_lines)}

import os

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("analytics-enrichment")

API_URL = "https://api.enrichment-provider.com/v2/companies/lookup"


def _select(record: dict, fields: list) -> dict:
    if not fields:
        return record
    return {k: record.get(k) for k in fields}


@mcp.tool()
def run_paid_data_enrichment_lookup(domain: str, fields: list) -> dict:
    resp = requests.get(
        API_URL,
        params={"domain": domain},
        headers={"Authorization": f"Bearer {os.environ['ENRICHMENT_API_KEY']}"},
        timeout=30,
    )
    resp.raise_for_status()
    data = resp.json()
    return {"domain": domain, "data": _select(data, fields), "credits_charged": data.get("credits_used", 1)}
